From 4a3f23ca05e0748c187c4660ac77b6d53abaf2a8 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:19:06 +0100
Subject: [PATCH] applet: show an error when the Vaults service is unavailable

When kded had just restarted or the plasmavault module wasn't loaded,
the failed D-Bus call was ignored and the applet claimed no vaults were
set up. Ask kded to load the module first, and say so if that fails.

BUG: 446437
---
 plasma/package/contents/ui/main.qml | 24 ++++++++++++++---
 plasma/vaultsmodel.cpp              | 42 +++++++++++++++++++++++++++++
 plasma/vaultsmodel.h                |  3 +++
 plasma/vaultsmodel_p.h              |  4 +++
 4 files changed, 69 insertions(+), 4 deletions(-)

diff --git a/plasma/package/contents/ui/main.qml b/plasma/package/contents/ui/main.qml
index e505271..709a336 100644
--- a/plasma/package/contents/ui/main.qml
+++ b/plasma/package/contents/ui/main.qml
@@ -32,7 +32,7 @@ PlasmoidItem {
     Plasmoid.busy: vaultsModelActions.isBusy

     Plasmoid.icon: {
-        let iconName = (vaultsModelActions.hasError ? "plasmavault_error" : "plasmavault");
+        let iconName = (vaultsModelActions.hasError || !vaultsModelActions.isServiceAvailable ? "plasmavault_error" : "plasmavault");

         if (inPanel) {
             return iconName += "-symbolic"
@@ -100,15 +100,31 @@ PlasmoidItem {

                     visible: vaultsList.count === 0

-                    iconName: "plasmavault"
-                    text: i18nd("plasmavault-kde", "No Vaults have been set up")
+                    iconName: root.vaultsModelActions.isServiceAvailable ? "plasmavault" : "plasmavault_error"
+                    text: root.vaultsModelActions.isServiceAvailable
+                        ? i18nd("plasmavault-kde", "No Vaults have been set up")
+                        : i18nd("plasmavault-kde", "Vaults are unavailable")
+                    explanation: root.vaultsModelActions.isServiceAvailable
+                        ? ""
+                        : i18nd("plasmavault-kde", "The Plasma Vault background service is not running.")

-                    helpfulAction: QQC2.Action {
+                    helpfulAction: root.vaultsModelActions.isServiceAvailable ? createVaultAction : retryAction
+
+                    QQC2.Action {
+                        id: createVaultAction
                         text: createAction.text
                         icon.name: createAction.icon.name

                         onTriggered: source => createAction.trigger()
                     }
+
+                    QQC2.Action {
+                        id: retryAction
+                        text: i18nd("plasmavault-kde", "Try Again")
+                        icon.name: "view-refresh-symbolic"
+
+                        onTriggered: source => root.vaultsModelActions.refresh()
+                    }
                 }
             }
         }
diff --git a/plasma/vaultsmodel.cpp b/plasma/vaultsmodel.cpp
index ba651e9..cb1f7d0 100644
--- a/plasma/vaultsmodel.cpp
+++ b/plasma/vaultsmodel.cpp
@@ -30,6 +30,7 @@ VaultsModel::Private::Private(VaultsModel *parent)
         // otherwise load the data
         if (newOwner.isEmpty()) {
             clearData();
+            setServiceAvailable(false);
         } else {
             loadData();
         }
@@ -45,14 +46,35 @@ void VaultsModel::Private::loadData()
     // Before loading the new data, lets forget everything
     clearData();

+    // Make sure the module is loaded, since right after kded starts
+    // (for example after a crash) it might not be there yet
+    auto message =
+        QDBusMessage::createMethodCall(QStringLiteral("org.kde.kded6"), QStringLiteral("/kded"), QStringLiteral("org.kde.kded6"), QStringLiteral("loadModule"));
+    message << QStringLiteral("plasmavault");
+    QDBusPendingReply<bool> reply = QDBusConnection::sessionBus().asyncCall(message);
+    auto watcher = new QDBusPendingCallWatcher(reply);
+    connect(watcher, &QDBusPendingCallWatcher::finished, q, [this, reply, watcher] {
+        watcher->deleteLater();
+        if (reply.isError() || !reply.value()) {
+            setServiceAvailable(false);
+            return;
+        }
+        loadDevices();
+    });
+}
+
+void VaultsModel::Private::loadDevices()
+{
     // Asynchronously load the devices
     QDBusPendingReply<VaultInfoList> reply = service.availableDevices();
     auto watcher = new QDBusPendingCallWatcher(reply);
     connect(watcher, &QDBusPendingCallWatcher::finished, q, [this, reply, watcher] {
         watcher->deleteLater();
         if (reply.isError()) {
+            setServiceAvailable(false);
             return;
         }
+        setServiceAvailable(true);
         const VaultInfoList &vaultList = reply.value();
         const int oldSize = vaultKeys.size();
         q->beginResetModel();
@@ -100,6 +122,16 @@ void VaultsModel::Private::clearData()
     q->endResetModel();
 }

+void VaultsModel::Private::setServiceAvailable(bool available)
+{
+    if (serviceAvailable == available) {
+        return;
+    }
+
+    serviceAvailable = available;
+    Q_EMIT q->isServiceAvailableChanged(available);
+}
+
 void VaultsModel::Private::onVaultAdded(const PlasmaVault::VaultInfo &vaultInfo)
 {
     const auto device = vaultInfo.device;
@@ -294,6 +326,11 @@ void VaultsModel::refresh()

 void VaultsModel::reloadDevices()
 {
+    if (!d->serviceAvailable) {
+        refresh();
+        return;
+    }
+
     d->service.updateStatus();
 }

@@ -370,6 +407,11 @@ bool VaultsModel::hasOpenVaults() const
     return !d->openVaults.isEmpty();
 }

+bool VaultsModel::isServiceAvailable() const
+{
+    return d->serviceAvailable;
+}
+
 SortedVaultsModelProxy::SortedVaultsModelProxy(QObject *parent)
     : QSortFilterProxyModel(parent)
     , m_source(new VaultsModel(this))
diff --git a/plasma/vaultsmodel.h b/plasma/vaultsmodel.h
index 9d609c0..40949f2 100644
--- a/plasma/vaultsmodel.h
+++ b/plasma/vaultsmodel.h
@@ -21,6 +21,7 @@ class VaultsModel : public QAbstractListModel
     Q_PROPERTY(bool isBusy READ isBusy NOTIFY isBusyChanged)
     Q_PROPERTY(bool hasError READ hasError NOTIFY hasErrorChanged)
     Q_PROPERTY(bool hasOpenVaults READ hasOpenVaults NOTIFY hasOpenVaultsChanged)
+    Q_PROPERTY(bool isServiceAvailable READ isServiceAvailable NOTIFY isServiceAvailableChanged)
     Q_PROPERTY(int count READ rowCount NOTIFY rowCountChanged)

 public:
@@ -77,11 +78,13 @@ public Q_SLOTS:
     bool isBusy() const;
     bool hasError() const;
     bool hasOpenVaults() const;
+    bool isServiceAvailable() const;

 Q_SIGNALS:
     void isBusyChanged(bool isBusy);
     void hasErrorChanged(bool hasError);
     void hasOpenVaultsChanged(bool hasOpenVaults);
+    void isServiceAvailableChanged(bool isServiceAvailable);
     void rowCountChanged(int count);

 private:
diff --git a/plasma/vaultsmodel_p.h b/plasma/vaultsmodel_p.h
index 335f8e0..7b26e49 100644
--- a/plasma/vaultsmodel_p.h
+++ b/plasma/vaultsmodel_p.h
@@ -29,7 +29,9 @@ public Q_SLOTS:
     void onVaultChanged(const PlasmaVault::VaultInfo &vaultData);

     void loadData();
+    void loadDevices();
     void clearData();
+    void setServiceAvailable(bool available);

 public:
     org::kde::plasmavault service;
@@ -39,6 +41,8 @@ public:
     QSet<QString> errorVaults;
     QSet<QString> openVaults;

+    bool serviceAvailable = true;
+
     VaultsModel *const q;
 };

